//! Exercise the original ROM generated by scripts/make-nes-test-rom.py.
use anyhow::{Result, ensure};
use romforge_core::Session;
use std::{fs, path::Path};
fn main() -> Result<()> {
    let args: Vec<_> = std::env::args_os().skip(1).collect();
    ensure!(args.len() == 2, "usage: check_nes CORE DIAGNOSTIC_ROM");
    let rom = fs::read(&args[1])?;
    // SAFETY: explicitly selected trusted development core.
    let mut session = unsafe { Session::load(Path::new(&args[0]), rom.clone(), "nes") }?;
    session.run_frames(120)?;
    // NES controller serial order: A B Select Start Up Down Left Right.
    for (button, expected) in [
        (8, 128),
        (0, 64),
        (2, 32),
        (3, 16),
        (4, 8),
        (5, 4),
        (6, 2),
        (7, 1),
    ] {
        session.set_buttons(1 << button);
        session.run_frames(3)?;
        let ram = session.save_ram()?;
        ensure!(
            ram[0] == expected,
            "button {button}: expected {expected}, got {}",
            ram[0]
        );
    }
    session.set_buttons(0);
    session.run_frames(3)?;
    let saved = session.save_ram()?;
    ensure!(saved[0] == 0, "controller release stuck");
    drop(session);
    let mut session = unsafe { Session::load(Path::new(&args[0]), rom, "nes") }?;
    session.restore_ram(&saved)?;
    ensure!(session.save_ram()? == saved, "battery save reload failed");
    println!(
        "NES A/B, Start/Select, D-pad, release and battery reload passed ({} bytes)",
        saved.len()
    );
    Ok(())
}
